import 'package:http_cache_mmkv_store/http_cache_mmkv_store.dart';
import 'package:dio/dio.dart';
import 'package:dio_cache_interceptor/dio_cache_interceptor.dart';

Future<void> setupDio() async {
  await MMKVCacheStore.initialise();
  final cacheStore = MMKVCacheStore();
  final cacheOptions = CacheOptions(store: cacheStore, policy: CachePolicy.request);
  final dio = Dio()..interceptors.add(DioCacheInterceptor(options: cacheOptions));
}
